import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence, useScroll, useTransform, useSpring, useMotionValue } from 'framer-motion';
import { Play, ArrowUpRight, Instagram, Mail, ChevronRight, Zap, Briefcase, Award, Sparkles, Send, Check, Loader2, Wand2, Bot, Github } from 'lucide-react';
import './App.css'; 

// --- COMPONENTS ---

// Logo: Black
const AuraLogo = React.memo(({ className = "w-8 h-8" }) => (
  <svg viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
    <motion.path 
      d="M50 5 L95 80 L5 80 Z" 
      stroke="#000000" 
      strokeWidth="4" 
      strokeLinecap="round" 
      strokeLinejoin="round"
      initial={{ pathLength: 0 }}
      animate={{ pathLength: 1 }}
      transition={{ duration: 2, ease: "easeInOut" }}
    />
    <motion.path 
      d="M50 30 L75 70 L25 70 Z" 
      fill="#000000"
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 0.1, scale: 1 }}
      transition={{ delay: 1, duration: 1 }}
    />
  </svg>
));

// Cursor: Black
const CustomCursor = React.memo(() => {
  const cursorX = useMotionValue(-100);
  const cursorY = useMotionValue(-100);
  const ringX = useMotionValue(-100);
  const ringY = useMotionValue(-100);

  const springConfig = { damping: 25, stiffness: 700, mass: 0.1 };
  const ringSpringConfig = { damping: 30, stiffness: 200, mass: 0.5 };

  const cursorXSpring = useSpring(cursorX, springConfig);
  const cursorYSpring = useSpring(cursorY, springConfig);
  const ringXSpring = useSpring(ringX, ringSpringConfig);
  const ringYSpring = useSpring(ringY, ringSpringConfig);

  const [isHovering, setIsHovering] = useState(false);

  useEffect(() => {
    const moveCursor = (e) => {
      cursorX.set(e.clientX - 4);
      cursorY.set(e.clientY - 4);
      ringX.set(e.clientX - 16);
      ringY.set(e.clientY - 16);
    };

    const handleMouseOver = (e) => {
      if (e.target.closest('a, button, input, textarea, .interactive')) {
        setIsHovering(true);
      } else {
        setIsHovering(false);
      }
    };

    window.addEventListener('mousemove', moveCursor);
    window.addEventListener('mouseover', handleMouseOver);

    return () => {
      window.removeEventListener('mousemove', moveCursor);
      window.removeEventListener('mouseover', handleMouseOver);
    };
  }, [cursorX, cursorY, ringX, ringY]);

  return (
    <>
      <motion.div
        className="custom-cursor fixed top-0 left-0 w-2 h-2 bg-black rounded-full pointer-events-none z-[100]"
        style={{ x: cursorXSpring, y: cursorYSpring, scale: isHovering ? 0 : 1 }}
      />
      <motion.div
        className="custom-cursor fixed top-0 left-0 w-8 h-8 border border-black/30 rounded-full pointer-events-none z-[99]"
        style={{ 
          x: ringXSpring, 
          y: ringYSpring,
          scale: isHovering ? 1.5 : 1,
          backgroundColor: isHovering ? 'rgba(0,0,0,0.05)' : 'transparent',
          borderColor: isHovering ? 'rgba(0,0,0,0)' : 'rgba(0,0,0,0.3)',
        }}
      />
    </>
  );
});

const MagneticButton = React.memo(({ children, className, onClick, primary = false }) => {
  const ref = useRef(null);
  const [position, setPosition] = useState({ x: 0, y: 0 });

  const handleMouse = (e) => {
    const { clientX, clientY } = e;
    const { height, width, left, top } = ref.current.getBoundingClientRect();
    const middleX = clientX - (left + width / 2);
    const middleY = clientY - (top + height / 2);
    setPosition({ x: middleX * 0.2, y: middleY * 0.2 });
  };

  return (
    <motion.button
      ref={ref}
      onMouseMove={handleMouse}
      onMouseLeave={() => setPosition({ x: 0, y: 0 })}
      animate={{ x: position.x, y: position.y }}
      transition={{ type: "spring", stiffness: 150, damping: 15, mass: 0.1 }}
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.98 }}
      onClick={onClick}
      className={`relative overflow-hidden rounded-full group interactive transition-shadow duration-300 ${
        primary 
          ? 'bg-black text-white font-semibold shadow-[0_8px_20px_rgba(0,0,0,0.15)] hover:shadow-[0_12px_25px_rgba(0,0,0,0.25)]' 
          : 'bg-white/60 border border-black/10 text-black backdrop-blur-[20px] shadow-[0_10px_30px_rgba(0,0,0,0.05)] hover:shadow-md hover:bg-white/80'
      } ${className}`}
    >
      <span className="relative z-10 flex items-center justify-center gap-2">
        {children}
      </span>
    </motion.button>
  );
});

const TiltCard = React.memo(({ children, className }) => {
  const ref = useRef(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const mouseXSpring = useSpring(x, { stiffness: 300, damping: 30 });
  const mouseYSpring = useSpring(y, { stiffness: 300, damping: 30 });
  
  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["10deg", "-10deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-10deg", "10deg"]);

  return (
    <motion.div
      ref={ref}
      onMouseMove={(e) => {
        if (!ref.current) return;
        const rect = ref.current.getBoundingClientRect();
        x.set((e.clientX - rect.left) / rect.width - 0.5);
        y.set((e.clientY - rect.top) / rect.height - 0.5);
      }}
      onMouseLeave={() => { x.set(0); y.set(0); }}
      style={{ rotateX, rotateY, transformStyle: "preserve-3d", boxShadow: "0 20px 50px rgba(0,0,0,0.05), inset 0 0 0 1px rgba(255,255,255,0.5), inset 0 20px 40px rgba(255,255,255,0.6)" }}
      className={`relative rounded-[24px] bg-white/30 backdrop-blur-[40px] p-8 transition-colors hover:bg-white/40 interactive ${className}`}
    >
      <div style={{ transform: "translateZ(40px)", transformStyle: "preserve-3d" }} className="w-full h-full">{children}</div>
      <motion.div 
        className="absolute inset-0 rounded-[24px] pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500"
        style={{
          background: useTransform(
            [mouseXSpring, mouseYSpring],
            ([mx, my]) => `radial-gradient(circle at ${(mx + 0.5) * 100}% ${(my + 0.5) * 100}%, rgba(255, 255, 255, 0.5), transparent 60%)`
          )
        }}
      />
    </motion.div>
  );
});

const SectionHeading = React.memo(({ children, subtitle }) => (
  <motion.div 
    initial={{ opacity: 0, y: 30 }}
    whileInView={{ opacity: 1, y: 0 }}
    viewport={{ once: true, margin: "-100px" }}
    transition={{ duration: 0.8, ease: "easeOut" }}
    className="mb-16"
  >
    {subtitle && (
      <h4 className="text-black/60 font-semibold tracking-wider uppercase text-sm mb-3 flex items-center gap-2">
        <Sparkles className="w-4 h-4 text-black" /> {subtitle}
      </h4>
    )}
    <h2 className="text-4xl md:text-6xl font-bold tracking-tighter text-black">
      {children}
    </h2>
  </motion.div>
));

const Loader = React.memo(({ onComplete }) => (
  <motion.div
    key="loader"
    exit={{ opacity: 0, filter: "blur(20px)" }}
    transition={{ duration: 1, ease: "easeInOut" }}
    className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-[#ffffff]"
  >
    <motion.div
      initial={{ scale: 0.8, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      transition={{ duration: 1, ease: "easeOut" }}
      className="flex flex-col items-center"
    >
      <AuraLogo className="w-20 h-20 mb-6" />
      <motion.h1 
        initial={{ y: 40 }}
        animate={{ y: 0 }}
        transition={{ delay: 0.5, duration: 0.8 }}
        className="text-3xl tracking-[0.3em] font-light text-black"
      >
        AURA
      </motion.h1>
    </motion.div>
    <motion.div 
      initial={{ width: 0 }}
      animate={{ width: "200px" }}
      transition={{ delay: 1, duration: 1.5 }}
      onAnimationComplete={onComplete}
      className="h-[1px] bg-gradient-to-r from-transparent via-black/50 to-transparent mt-8"
    />
  </motion.div>
));

// --- GEMINI API HELPER ---
const callGeminiAPI = async (prompt, systemPrompt) => {
  const apiKey = ""; 
  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-preview-09-2025:generateContent?key=${apiKey}`;
  const payload = { contents: [{ parts: [{ text: prompt }] }], systemInstruction: { parts: [{ text: systemPrompt }] } };
  
  for (let i = 0; i < 3; i++) {
    try {
      const response = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
      const result = await response.json();
      return result.candidates?.[0]?.content?.parts?.[0]?.text || "No response generated.";
    } catch (error) { if (i === 2) return "AI service temporarily unavailable."; await new Promise(res => setTimeout(res, 1000)); }
  }
};

const AIConceptStudio = React.memo(() => {
  const [idea, setIdea] = useState("");
  const [concept, setConcept] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);

  const handleGenerate = async () => {
    if (!idea.trim()) return;
    setIsGenerating(true); setConcept("");
    const systemPrompt = "You are a creative director. Generate a 3-part viral video concept (Hook, Build-up, CTA) under 100 words.";
    try {
      const result = await callGeminiAPI(`Idea: ${idea}`, systemPrompt);
      setConcept(result);
    } catch (err) { setConcept("Error generating concept."); } 
    finally { setIsGenerating(false); }
  };

  return (
    <div className="relative rounded-[3rem] bg-white/40 backdrop-blur-[40px] p-10 md:p-16 border border-white/60 shadow-[0_20px_50px_rgba(0,0,0,0.05)] overflow-hidden">
      <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none"><Bot className="w-40 h-40 text-black" /></div>
      <div className="relative z-10 max-w-2xl">
        <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white/60 border border-black/5 text-sm font-bold tracking-widest uppercase mb-6 shadow-sm"><Sparkles className="w-4 h-4 text-indigo-500" /> AI Co-Creator</div>
        <h3 className="text-3xl md:text-5xl font-bold tracking-tighter mb-4 text-black">Brainstorm your next viral hit.</h3>
        <div className="flex flex-col sm:flex-row gap-4 mb-8">
          <input type="text" value={idea} onChange={(e) => setIdea(e.target.value)} placeholder="e.g., A sleek new coffee brand..." className="flex-1 bg-white/50 border border-black/10 rounded-2xl px-6 py-4 text-black focus:outline-none focus:border-black/30 focus:bg-white transition-all shadow-inner" onKeyDown={(e) => e.key === 'Enter' && handleGenerate()} />
          <MagneticButton primary onClick={handleGenerate} disabled={isGenerating}>{isGenerating ? <><Loader2 className="w-5 h-5 animate-spin" /> Thinking...</> : "✨ Generate"}</MagneticButton>
        </div>
        <AnimatePresence mode="wait">{concept && <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="p-6 rounded-2xl bg-white/60 border border-black/5 shadow-sm text-black/80 whitespace-pre-line">{concept}</motion.div>}</AnimatePresence>
      </div>
    </div>
  );
});

export default function App() {
  const [loading, setLoading] = useState(true);
  const [formState, setFormState] = useState({ name: '', email: '', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isDraftingMessage, setIsDraftingMessage] = useState(false);

  const handleInputChange = (e) => setFormState({ ...formState, [e.target.name]: e.target.value });

  const handleDraftMessage = async () => {
    if (!formState.message.trim()) return;
    setIsDraftingMessage(true);
    const systemPrompt = "Draft a short, professional inquiry email.";
    try {
      const drafted = await callGeminiAPI(`Notes: ${formState.message}`, systemPrompt);
      setFormState(prev => ({ ...prev, message: drafted }));
    } catch (err) { console.error(err); } 
    finally { setIsDraftingMessage(false); }
  };

  const handleSubmit = async (e) => {
    e.preventDefault(); setIsSubmitting(true);
    // Simulate submission for demo purposes
    setTimeout(() => { setIsSubmitting(false); setIsSubmitted(true); setFormState({ name: '', email: '', message: '' }); setTimeout(() => setIsSubmitted(false), 5000); }, 1500);
  };

  useEffect(() => { document.title = "Aura – Visual Experience by Vivin M"; }, []);

  return (
    <>
      <CustomCursor />
      <AnimatePresence>{loading && <Loader onComplete={() => setLoading(false)} />}</AnimatePresence>
      
      {/* 🌟 COLORFUL CONFETTI PARTICLES ADDED HERE */}
      <div id="particles1"></div>
      <div id="particles2"></div>
      <div id="particles3"></div>

      {!loading && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 1.2 }} className="relative z-10">
          
          <nav className="fixed top-0 w-full z-50 px-6 py-6 md:px-12 flex justify-between items-center bg-white/70 backdrop-blur-md border-b border-white/40">
            <div className="flex items-center gap-3"><AuraLogo className="w-8 h-8" /><span className="text-xl font-bold tracking-widest uppercase text-black">Aura</span></div>
            <MagneticButton className="px-6 py-2 text-sm hidden md:flex" onClick={() => document.getElementById('contact').scrollIntoView()}>Let's Talk</MagneticButton>
          </nav>

          <section className="min-h-screen flex flex-col justify-center px-6 md:px-12 pt-20">
            <div className="max-w-6xl mx-auto w-full relative z-10">
              <div className="overflow-hidden mb-4"><motion.p initial={{ y: "100%" }} animate={{ y: 0 }} transition={{ delay: 0.2, duration: 0.8 }} className="text-black/60 font-semibold tracking-widest uppercase text-sm md:text-base mb-4">Vivin M • @aura.edit_ae</motion.p></div>
              <div className="overflow-hidden py-2"><motion.h1 initial={{ y: "100%" }} animate={{ y: 0 }} transition={{ delay: 0.4, duration: 1 }} className="text-5xl md:text-8xl lg:text-9xl font-bold tracking-tighter leading-[1.1] text-black">Crafting Visual<br/>Stories in 4K.</motion.h1></div>
              <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.8 }} className="text-xl md:text-2xl text-black/60 mt-8 max-w-2xl font-light"><span className="text-black font-semibold">Editor.</span> Creator. Entrepreneur. <span className="text-black italic">AI Student.</span></motion.p>
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 1 }} className="flex flex-wrap gap-4 mt-12">
                <MagneticButton primary className="px-8 py-4 text-lg" onClick={() => document.getElementById('portfolio').scrollIntoView()}>View My Work <ArrowUpRight className="w-5 h-5 text-white" /></MagneticButton>
                <MagneticButton className="px-8 py-4 text-lg" onClick={() => document.getElementById('contact').scrollIntoView()}>Contact Me</MagneticButton>
              </motion.div>
            </div>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 1.5 }} className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2">
              <span className="text-xs tracking-widest text-black/40 uppercase font-semibold">Scroll</span>
              <div className="w-[1px] h-12 bg-black/10 relative overflow-hidden"><motion.div animate={{ y: ["-100%", "100%"] }} transition={{ repeat: Infinity, duration: 1.5, ease: "linear" }} className="absolute top-0 left-0 w-full h-1/2 bg-black" /></div>
            </motion.div>
          </section>

          <section id="about" className="py-32 px-6 md:px-12 max-w-7xl mx-auto">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-20">
              <div>
                <SectionHeading subtitle="The Mindset">Beyond Editing.</SectionHeading>
                <motion.div initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} className="space-y-6 text-lg text-black/70 leading-relaxed font-light">
                  <p>I'm Vivin M, a professional video editor, entrepreneur, and an <strong className="text-black font-semibold">AI student</strong>. With <strong className="text-black font-semibold">2.5+ years experience</strong>, I craft high-retention 4K stories.</p>
                  <div className="pt-6 border-t border-black/10 flex gap-12">
                    <div><div className="text-4xl font-bold text-black mb-2">2.5<span className="text-black/40">+</span></div><div className="text-sm uppercase tracking-wider text-black/50 font-semibold">Years Editing</div></div>
                    <div><div className="text-4xl font-bold text-black mb-2">3<span className="text-black/40">+</span></div><div className="text-sm uppercase tracking-wider text-black/50 font-semibold">Years Business</div></div>
                  </div>
                </motion.div>
              </div>
              <div className="space-y-8">
                {[{ name: 'Adobe After Effects', value: 95 }, { name: 'Premiere Pro', value: 92 }, { name: 'Motion Design', value: 88 }].map((skill, i) => (
                  <div key={i} className="group"><div className="flex justify-between text-sm mb-2 font-semibold text-black"><span>{skill.name}</span><span>{skill.value}%</span></div><div className="h-2 w-full bg-black/5 rounded-full relative"><motion.div initial={{ width: 0 }} whileInView={{ width: `${skill.value}%` }} className="absolute top-0 left-0 h-full bg-black rounded-full" /></div></div>
                ))}
              </div>
            </div>
          </section>

          <section className="py-32 px-6 md:px-12 bg-[#F7F9FC]">
            <div className="max-w-7xl mx-auto">
              <SectionHeading subtitle="Entrepreneurship">Building Businesses.</SectionHeading>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <TiltCard className="flex flex-col justify-between"><div className="mb-8"><Zap className="w-8 h-8 text-black mb-6" /><h3 className="text-3xl font-bold mb-4 text-black">Granite Laser Engraving</h3><p className="text-black/60 text-lg">Scaled to ₹6+ Lakhs revenue.</p></div><div className="text-black font-semibold flex items-center gap-2">View Case Study <ChevronRight className="w-4 h-4" /></div></TiltCard>
                <TiltCard className="flex flex-col justify-between"><div className="mb-8"><Briefcase className="w-8 h-8 text-black mb-6" /><h3 className="text-3xl font-bold mb-4 text-black">Biofloc Farming</h3><p className="text-black/60 text-lg">Sustainable aquaculture tech.</p></div><div className="text-black font-semibold flex items-center gap-2">View Details <ChevronRight className="w-4 h-4" /></div></TiltCard>
              </div>
            </div>
          </section>

          <section id="portfolio" className="py-32 px-6 md:px-12 max-w-7xl mx-auto">
            <SectionHeading subtitle="Selected Works">Visual Portfolio.</SectionHeading>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* VIDEO CARD - Replaced with your Reel */}
              <div className="aspect-video bg-black/5 rounded-[24px] relative overflow-hidden group cursor-pointer shadow-sm">
                 <video src="/reel1.mp4" autoPlay loop muted playsInline className="w-full h-full object-cover" />
                 <div className="absolute inset-0 bg-black/10 group-hover:bg-transparent transition-colors" />
                 <div className="absolute bottom-6 left-6 text-white font-bold text-2xl drop-shadow-md">Cinematic Reel 01</div>
              </div>
              {[2, 3, 4].map(id => (
                <div key={id} className="aspect-video bg-black/5 rounded-[24px] relative overflow-hidden group cursor-pointer flex items-center justify-center text-black/20 font-bold text-2xl">Project {id}</div>
              ))}
            </div>
          </section>

          <section className="py-16 px-6 md:px-12 max-w-7xl mx-auto"><AIConceptStudio /></section>

          <section id="contact" className="py-32 px-6 md:px-12 bg-white">
            <div className="max-w-4xl mx-auto bg-white/60 border border-black/5 backdrop-blur-xl rounded-[3rem] p-10 md:p-20 shadow-xl">
              <h2 className="text-5xl md:text-7xl font-bold mb-6 text-black">Let's Create.</h2>
              <div className="grid md:grid-cols-2 gap-12">
                <div>
                  <h4 className="text-sm uppercase tracking-widest text-black/50 font-semibold mb-4">Socials</h4>
                  <div className="flex flex-col gap-3">
                    <a href="https://instagram.com/aura.edit_ae" className="flex items-center gap-3 text-xl font-bold text-black"><Instagram /> @aura.edit_ae</a>
                    <a href="mailto:auraeditae@gmail.com" className="flex items-center gap-3 text-xl font-bold text-black"><Mail /> Email Me</a>
                  </div>
                </div>
                <form onSubmit={handleSubmit} className="space-y-6">
                  <input name="name" value={formState.name} onChange={handleInputChange} placeholder="Name" className="w-full bg-transparent border-b border-black/10 pb-4 text-black focus:outline-none focus:border-black" />
                  <input name="email" value={formState.email} onChange={handleInputChange} placeholder="Email" className="w-full bg-transparent border-b border-black/10 pb-4 text-black focus:outline-none focus:border-black" />
                  <div className="relative">
                    <div className="flex justify-between mb-2"><span className="text-xs font-bold text-black/50 uppercase">Message</span><button type="button" onClick={handleDraftMessage} disabled={isDraftingMessage} className="text-xs font-bold text-indigo-600 flex items-center gap-1">{isDraftingMessage ? <Loader2 className="w-3 h-3 animate-spin"/> : <Wand2 className="w-3 h-3"/>} AI Draft</button></div>
                    <textarea name="message" value={formState.message} onChange={handleInputChange} rows={3} className="w-full bg-transparent border-b border-black/10 pb-4 text-black focus:outline-none focus:border-black resize-none" />
                  </div>
                  <MagneticButton primary disabled={isSubmitting}>{isSubmitting ? "Sending..." : isSubmitted ? "Sent!" : "Send Message"}</MagneticButton>
                </form>
              </div>
            </div>
          </section>

          <footer className="py-8 text-center text-black/40 text-sm border-t border-black/5">© {new Date().getFullYear()} Aura by Vivin M.</footer>
        </motion.div>
      )}
    </>
  );
}
